import datetime
import unittest
from decimal import Decimal

import pennywise
from pennywise import Entry, ParseError, parse


class ValidLines(unittest.TestCase):
    def test_full_entry(self):
        (e,) = parse("2024-03-01 salary 2500.00 March pay")
        self.assertEqual(e.date, datetime.date(2024, 3, 1))
        self.assertEqual(e.category, "salary")
        self.assertEqual(e.amount, Decimal("2500.00"))
        self.assertIsInstance(e.amount, Decimal)
        self.assertEqual(e.note, "March pay")

    def test_no_note_is_empty_string(self):
        (e,) = parse("2024-03-05 Rent -900")
        self.assertEqual(e.note, "")

    def test_order_preserved(self):
        es = parse("2024-03-05 b 1\n2024-03-01 a 2\n")
        self.assertEqual([e.category for e in es], ["b", "a"])

    def test_empty_text(self):
        self.assertEqual(parse(""), [])

    def test_valid_amounts(self):
        for text, want in [("2500", "2500"), ("+2500", "2500"), ("2500.00", "2500.00"),
                           ("12.5", "12.5"), ("-0.99", "-0.99"), ("12", "12")]:
            (e,) = parse("2024-01-01 x " + text)
            self.assertEqual(e.amount, Decimal(want), text)

    def test_invalid_amounts(self):
        for text in ["12.505", "1,000.00", "abc", ".5", "12.", "1e3", "--5", "+-5", "5x"]:
            with self.assertRaises(ParseError, msg=text):
                parse("2024-01-01 x " + text)

    def test_category_case_folded(self):
        self.assertEqual(parse("2024-01-01 Rent 1")[0].category, "rent")
        self.assertEqual(parse("2024-01-01 RENT 1")[0].category, "rent")

    def test_tabs_and_mixed_separators(self):
        (e,) = parse("2024-01-01\t\tfood \t 5\t a  note")
        self.assertEqual((e.category, e.amount, e.note), ("food", Decimal("5"), "a  note"))

    def test_note_trimmed_inner_spaces_kept(self):
        (e,) = parse("2024-01-01 food 5   weekly   big  shop \t ")
        self.assertEqual(e.note, "weekly   big  shop")

    def test_leading_whitespace_allowed(self):
        (e,) = parse("   2024-01-01 food 5")
        self.assertEqual(e.category, "food")

    def test_blank_and_comment_lines_ignored(self):
        text = "# c\n\n   \n\t\n  # indented\n2024-01-01 a 1\n#2024-01-02 b 2\n"
        self.assertEqual(len(parse(text)), 1)

    def test_crlf(self):
        es = parse("2024-01-01 a 1 n\r\n2024-01-02 b 2\r\n")
        self.assertEqual([e.note for e in es], ["n", ""])

    def test_no_trailing_newline(self):
        self.assertEqual(len(parse("2024-01-01 a 1")), 1)

    def test_note_may_contain_hash(self):
        self.assertEqual(parse("2024-01-01 a 1 # not a comment")[0].note, "# not a comment")

    def test_entry_frozen(self):
        e = parse("2024-01-01 a 1")[0]
        with self.assertRaises(Exception):
            e.category = "z"
        self.assertEqual(e, Entry(datetime.date(2024, 1, 1), "a", Decimal("1"), ""))


class InvalidLines(unittest.TestCase):
    def assertBad(self, text, line):
        with self.assertRaises(ParseError) as ctx:
            parse(text)
        self.assertEqual(ctx.exception.line, line)
        self.assertIn("line %d" % line, str(ctx.exception))
        self.assertTrue(str(ctx.exception).startswith("line %d: " % line))
        return ctx.exception

    def test_is_value_error(self):
        self.assertTrue(issubclass(ParseError, ValueError))
        self.assertIs(pennywise.ParseError, ParseError)

    def test_too_few_fields(self):
        self.assertBad("2024-01-01 food", 1)
        self.assertBad("2024-01-01", 1)

    def test_bad_date_format(self):
        for d in ["2024-1-01", "24-01-01", "2024/01/01", "20240101", "2024-01-011", "x"]:
            self.assertBad(d + " food 5", 1)

    def test_nonexistent_date(self):
        self.assertBad("2024-02-30 food 5", 1)
        self.assertBad("2023-02-29 food 5", 1)
        self.assertBad("2024-13-01 food 5", 1)
        self.assertBad("2024-00-10 food 5", 1)
        self.assertBad("0000-01-01 food 5", 1)
        self.assertEqual(len(parse("2024-02-29 food 5")), 1)

    def test_unicode_digits_rejected(self):
        self.assertBad("2024-01-01 food ٥", 1)
        self.assertBad("٢024-01-01 food 5", 1)

    def test_line_number_counts_blank_and_comment_lines(self):
        text = "# header\n\n2024-01-01 a 1\n\n# c\n2024-01-02 b 12.505\n"
        self.assertBad(text, 6)

    def test_line_number_with_crlf(self):
        self.assertBad("2024-01-01 a 1\r\n\r\nbad\r\n", 3)

    def test_cr_only_file_with_comment_first(self):
        es = parse("# c\r\r2024-03-01 a 1 note\r2024-03-02 b 2\r")
        self.assertEqual([(e.category, e.note) for e in es], [("a", "note"), ("b", "")])

    def test_cr_only_several_entries_keep_notes(self):
        es = parse("2024-03-01 a 1 note\r2024-03-02 a 1 two\r")
        self.assertEqual([e.note for e in es], ["note", "two"])
        self.assertEqual(len(parse("2024-03-01 a 1\r2024-03-02 b 2\r")), 2)

    def test_cr_only_error_reports_line_number(self):
        exc = self.assertBad("# c\r\r2024-03-01 a 1 note\r2024-02-30 a 1\r", 4)
        self.assertEqual(str(exc), "line 4: invalid date '2024-02-30'")

    def test_mixed_line_endings(self):
        es = parse("2024-01-01 a 1\n2024-01-02 b 2\r\n2024-01-03 c 3\r2024-01-04 d 4 n")
        self.assertEqual([e.category for e in es], ["a", "b", "c", "d"])
        self.assertBad("2024-01-01 a 1\n2024-01-02 b 2\r\n\r2024-01-03 c 3\rbad\n", 5)

    def test_crlf_counts_as_one_break(self):
        self.assertBad("\r\n\r\nbad", 3)

    def test_message_names_amount(self):
        exc = self.assertBad("\n\n\n2024-01-01 a 12.505", 4)
        self.assertEqual(str(exc), "line 4: invalid amount '12.505'")

    def test_first_error_reported(self):
        self.assertBad("bad\nworse\n", 1)


